INSERT INTO public.scenarios (
  scenario_code, subject, competency, developmental_band, difficulty,
  prompt, options, learning_objective, hint,
  irt_a, irt_b, irt_c, is_active, usage_count
) VALUES
('ENG-34-UND-01', 'English Literacy', 'understanding', '3-4', 'standard', 'Read the sentence: "Leo the puppy buried his favorite rubber bone under the old oak tree so his sister Maya would not chew it." Why did Leo bury the bone?', '[{"text":"He wanted to keep it safe from Maya.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"He forgot where the tree was.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"He disliked playing with rubber toys.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Maya instructed him to bury it.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Identifying character motivation and causal relationships in narrative text.', 'Look for the reason right after the word "so" in the sentence.', 1.1, -1.7, 0.25, true, 0),
('ENG-34-UND-02', 'English Literacy', 'understanding', '3-4', 'standard', 'Read: "Although it was pouring rain, Sarah put on her yellow raincoat and walked happily toward the giant puddle." How did Sarah feel about the rainy weather?', '[{"text":"She felt gloomy and wanted to stay indoors.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"She was frightened of getting her clothes wet.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"She was joyful and excited to play in the rain.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"She was angry that her trip was cancelled.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring character feelings and attitudes from actions and descriptive words.', 'Notice the word "happily" and how Sarah walked toward the puddle.', 1.15, -1.5, 0.25, true, 0),
('ENG-34-UND-03', 'English Literacy', 'understanding', '3-4', 'standard', '"Every winter, the bear retreats into a cozy cave and enters a deep sleep until spring flowers bloom." What is the main idea of this sentence?', '[{"text":"Spring flowers grow inside dark caves.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Bears hibernate in caves during the cold winter months.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Bears only wake up when other animals call them.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Winter is the best season for bears to hunt food.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Determining the main idea of a short informational sentence.', 'Consider what the whole sentence is describing about the bear’s winter habits.', 1.2, -1.4, 0.25, true, 0),
('ENG-34-UND-04', 'English Literacy', 'understanding', '3-4', 'standard', '"Toby dropped his ice cream cone on the sidewalk. His lower lip quivered, and tears welled up in his eyes." How does Toby feel?', '[{"text":"Disappointed and sad about losing his treat.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Surprised by how warm the sidewalk was.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Proud of sharing his ice cream with ants.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Bored and ready to go home.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Inferring emotional states from physical character cues.', 'What do a quivering lip and tears usually show?', 1.1, -1.6, 0.25, true, 0),
('ENG-34-UND-05', 'English Literacy', 'understanding', '3-4', 'standard', '"The little red hen asked her barnyard friends to help plant wheat seeds, but the duck and cat were too busy napping under the porch." What does this tell us about the duck and cat?', '[{"text":"They were skilled wheat farmers.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They were unwilling to help with farm chores.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"They were afraid of small seeds.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"They wanted to plant corn instead.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing character traits and behaviors in fables.', 'Notice that they chose to nap instead of helping.', 1.2, -1.3, 0.25, true, 0),
('ENG-34-UND-06', 'English Literacy', 'understanding', '3-4', 'advanced', '"The grandfather clock in the hallway stood like a tall wooden soldier guarding the quiet house." What comparison is being made here?', '[{"text":"The steady, upright clock is compared to a standing soldier.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"A real soldier is hiding inside the wooden clock.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The house is actively being attacked by an army.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The grandfather prefers soldiers over clocks.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting simple similes and figurative imagery.', 'Look for the word "like" which connects the clock and the soldier.', 1.3, -0.9, 0.25, true, 0),
('ENG-34-UND-07', 'English Literacy', 'understanding', '3-4', 'advanced', '"The desert chameleon blended so perfectly into the sand that the hawk flew right past without noticing." Why was the hawk unable to spot the chameleon?', '[{"text":"The chameleon ran into an underground tunnel.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The hawk was flying backward.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The sand was too bright for any bird to see.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"The chameleon used camouflage to match the color of the ground.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]}]'::jsonb, 'Understanding cause and effect in descriptive informational passages.', 'Focus on how blending into the sand protects the chameleon.', 1.25, -0.8, 0.25, true, 0),
('ENG-34-UND-08', 'English Literacy', 'understanding', '3-4', 'advanced', '"After three hours of hiking up the rocky trail, Anya finally saw the mountain peak gleaming in the afternoon sun. She took a deep breath and smiled." What is the theme of this moment?', '[{"text":"Effort and perseverance leading to a rewarding achievement.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"The dangers of hiking without proper hiking shoes.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Why mountains are colder than valley plains.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"How sunlight can damage your vision.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Deriving overarching theme from narrative resolution.', 'Consider the effort Anya put in and how she felt when she reached her goal.', 1.35, -0.7, 0.25, true, 0),
('ENG-34-UND-09', 'English Literacy', 'understanding', '3-4', 'olympiad', '"The sudden silence in the aviary was louder than any squawk; every bird froze as a shadow glided overhead." Why does the author call the silence "louder than any squawk"?', '[{"text":"To prove that silence creates physical sound waves.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"Because the birds were screaming in high-pitched frequencies.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"To emphasize how dramatic, alarming, and noticeable the quiet was.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"Because the roof of the aviary collapsed.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Analyzing literary paradox and authorial emphasis in Grade 3-4 text.', 'When everything goes dead silent instantly, what does that sudden change feel like?', 1.5, -0.4, 0.25, true, 0),
('ENG-34-UND-10', 'English Literacy', 'understanding', '3-4', 'olympiad', '"Grandma''s kitchen was always a busy workshop of simmering pots, flying flour, and stories passed down through generations." What does the word "workshop" suggest about the kitchen?', '[{"text":"It was an untidy and hazardous factory environment.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was used for repairing broken wooden chairs and tools.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]},{"text":"It was an active, creative place where food and traditions were lovingly crafted.","correct":true,"evidence":[{"competency":"understanding","earnedWeight":1}]},{"text":"It was strictly reserved for professional cooks.","correct":false,"evidence":[{"competency":"understanding","earnedWeight":0}]}]'::jsonb, 'Interpreting metaphorical language and connotative meaning.', 'Think about what happens in a workshop—things are made with care and effort.', 1.45, -0.3, 0.25, true, 0),
('ENG-34-LOC-01', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Notice: "School Library Schedule: Monday–Thursday: 8:00 AM – 3:30 PM. Friday: Closed for shelf organization." On which day is the library closed for shelf organization?', '[{"text":"Friday","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Monday","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Wednesday","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Thursday","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Direct retrieval of specific facts from simple schedules.', 'Scan the notice for the word "Closed" and look at the day listed right before it.', 1.2, -1.8, 0.25, true, 0),
('ENG-34-LOC-02', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Recipe Card: "Honey Berry Parfait: 1 cup Greek yogurt, 0.5 cup rolled oats, 2 tablespoons wild honey, 1 sliced ripe kiwi. Chill in the refrigerator for 15 minutes before serving." How much wild honey is needed?', '[{"text":"15 minutes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"1 cup","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"0.5 cup","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"2 tablespoons","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating precise measurements and ingredients in functional procedural text.', 'Locate the ingredient "wild honey" and read the amount specified.', 1.25, -1.7, 0.25, true, 0),
('ENG-34-LOC-03', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Museum Flyer: "Dinosaur Discovery Hall: Level 1. Space & Rockets Gallery: Level 3. Butterfly Pavilion: Rooftop Garden (Level 4)." On which level can visitors find the Space & Rockets Gallery?', '[{"text":"Level 4","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Level 1","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Level 2","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Level 3","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Scanning informational brochures for specific location details.', 'Search directly for the words "Space & Rockets Gallery".', 1.3, -1.6, 0.25, true, 0),
('ENG-34-LOC-04', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Weather Report: "Sunrise will occur at 6:15 AM. Highest daytime temperature will reach 28°C with moderate breezes from the northeast." What is the expected peak temperature?', '[{"text":"15°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"6:15 AM","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"28°C","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"35°C","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Retrieving numerical data from short informational reports.', 'Find the section mentioning temperature.', 1.2, -1.5, 0.25, true, 0),
('ENG-34-LOC-05', 'English Literacy', 'locatingInformation', '3-4', 'standard', 'Pet Care Guide: "Hamsters must be given fresh water every morning. Clean their wood shaving bedding once each week, and provide fresh carrot slices twice a week." How often should hamster bedding be cleaned?', '[{"text":"Every morning","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Once each week","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Twice a week","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Once a month","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Distinguishing between multiple time frequencies in a procedural passage.', 'Pay close attention to what corresponds specifically to "bedding".', 1.35, -1.4, 0.25, true, 0),
('ENG-34-LOC-06', 'English Literacy', 'locatingInformation', '3-4', 'advanced', 'School Bus Rules: "Students must remain seated until the bus halts completely. Backpacks must be placed beneath your seat or on your lap. Eating peanuts is strictly forbidden." Where should backpacks be stored?', '[{"text":"In the overhead luggage rack","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"In the aisle between seats","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Beneath the seat or on the student''s lap","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Next to the bus driver","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Extracting specific rules and storage instructions from safety guidelines.', 'Look for the sentence starting with "Backpacks".', 1.3, -1, 0.25, true, 0),
('ENG-34-LOC-07', 'English Literacy', 'locatingInformation', '3-4', 'advanced', 'Camp Itinerary: "08:00 Birdwatching along Maple Creek; 10:30 Kayak paddling practice; 12:30 Outdoor campfire lunch; 14:00 Orienteering navigation game." What activity takes place right before lunch?', '[{"text":"Orienteering navigation game","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Birdwatching along Maple Creek","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Kayak paddling practice","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"Campfire cleanup","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Interpreting chronological order in daily itineraries.', 'Look at the activity scheduled at 10:30, right before the 12:30 lunch.', 1.4, -0.9, 0.25, true, 0),
('ENG-34-LOC-08', 'English Literacy', 'locatingInformation', '3-4', 'advanced', 'Plant Factfile: "The Venus Flytrap is native only to the coastal bogs of North and South Carolina. Its leaves close in roughly 0.1 seconds when trigger hairs are brushed." In how much time do the leaves snap shut?', '[{"text":"10 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Roughly 0.1 seconds","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"1 minute","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"30 seconds","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Locating exact numerical scientific facts in descriptive prose.', 'Scan for the number followed by the time unit "seconds".', 1.35, -0.8, 0.25, true, 0),
('ENG-34-LOC-09', 'English Literacy', 'locatingInformation', '3-4', 'olympiad', 'Historical Log: "Captain Miller documented that the schooner arrived at Port Jackson on October 14, carrying 120 barrels of olive oil, 45 crates of dried figs, and three boxes of brass navigation sextants." How many crates of dried figs were recorded?', '[{"text":"120 barrels","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"45 crates","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]},{"text":"3 boxes","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"14 crates","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]}]'::jsonb, 'Scanning dense inventory lists for precise item-quantity pairings.', 'Pair each number with its exact cargo description.', 1.5, -0.5, 0.25, true, 0),
('ENG-34-LOC-10', 'English Literacy', 'locatingInformation', '3-4', 'olympiad', 'Wildlife Bulletin: "The Arctic tern migrates from Greenland to Antarctica and back each year, covering nearly 71,000 kilometers annually—the longest recorded journey of any animal on Earth." Between which two geographic regions does this bird travel?', '[{"text":"Norway and South Africa","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Canada and Australia","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Alaska and South America","correct":false,"evidence":[{"competency":"locatingInformation","earnedWeight":0}]},{"text":"Greenland and Antarctica","correct":true,"evidence":[{"competency":"locatingInformation","earnedWeight":1}]}]'::jsonb, 'Locating origin and destination entities in geographic informational text.', 'Look for the "from ... to ..." phrase in the passage.', 1.45, -0.4, 0.25, true, 0)
